 "content": "from collections import Counter


def transform(grid):
    """Copy the distinctive colored shape into every all-zero matching position."""
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return out
    marker = min(counts, key=lambda color: counts[color])
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == marker]
    if not points:
        return out

    height, width = len(grid), len(grid[0])
    min_r = min(r for r, _ in points)
    min_c = min(c for _, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]
    shape_h = max(r for r, _ in shape) + 1
    shape_w = max(c for _, c in shape) + 1

    for top in range(height - shape_h + 1):
        for left in range(width - shape_w + 1):
            cells = [(top + dr, left + dc) for dr, dc in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = marker
    return out
